INSERT INTO `state` VALUES (1,'吉隆坡','马来西亚的首都，拥有丰富的文化遗产和现代化的城市景观，双子塔作为标志性建筑','data:image/jpeg;base64,','west coast');
INSERT INTO `state` VALUES (2,'槟城','马来西亚的美食天堂和文化熔炉，以其丰富的历史遗迹和美丽的海滩闻名','data:image/jpeg;base64,','west coast'),(3,'柔佛','马来西亚最南端的州属，只与新加坡相距一公里，是重要的经济中心','data:image/jpeg;base64,','west coast');
INSERT INTO `state` VALUES (4,'沙巴','马来西亚的“风下之乡”，京那巴鲁山和西巴丹岛是游客的热门目的地','data:image/jpeg;base64,','east'),(5,'砂拉越','马来西亚最大的州属，以其丰富的原住民文化和热带雨林闻名','data:image/jpeg;base64,','east'),(6,'彭亨','马来西亚半岛最大的州属，首付关丹是一个美丽的海滨城市，云顶高原作为标志性景点','data:image/webp;base64,','east coast');
INSERT INTO `state` VALUES (7,'霹雳','马来西亚的“银州”，以其丰富的锡矿历史和美丽的自然景观闻名','data:image/webp;base64,','west coast'),(8,'马六甲','马来西亚的历史名城，被联合国教科文组织列为世界文化遗产，是游客必访之地','data:image/webp;base64,','west coast');
INSERT INTO `state` VALUES (9,'雪兰莪','马来西亚最发达的州属，以其现代化的城市和丰富的文化遗产闻名','data:image/jpeg;base64,','west coast'),(10,'吉打','马来西亚的“稻米之乡”，以其广阔的稻田和宁静的乡村风光著称','data:image/jpeg;base64,','west coast');
INSERT INTO `state` VALUES (11,'登嘉楼','闻名于美丽的海滩和丰富的马来文化，拥有许多古老的清真寺和博物馆','data:image/jpeg;base64,','east coast'),(12,'森美兰','闻名于独特的米南加保文化和美丽的自然风光，拥有丰富的文化遗产和美食','data:image/jpeg;base64,','west coast'),(13,'玻璃市','马来西亚最小的州属，以其宁静的乡村风光和农业活动闻名','data:image/jpeg;base64,','west coast');
INSERT INTO `state` VALUES (14,'吉兰丹','马来西亚的文化重镇，以其传统艺术、手工艺品和独特的马来文化闻名','data:image/jpeg;base64,','east coast');
/*!40000 ALTER TABLE `state` ENABLE KEYS */;
UNLOCK TABLES;

